const cols=['code','hex','name'];
// hex — тот же код как на радио, 4 знака (advMfr в modules/phonelink-kernels.js, r.mfr.companyId в BLE-рекламе): lookup
// по hex прямо из записи, без parseInt (в выражениях Table его нет — см. TR_FN в table-rules.js)
const out=rows.map(r=>({code:r[0],hex:r[0].toString(16).padStart(4,'0'),name:r[1]}));
const seen=new Set(); for(const r of out){ if(seen.has(r.code)) throw new Error('duplicate code '+r.code); seen.add(r.code); }
fs.writeFileSync(new URL('../data/bluetooth-companies.json',import.meta.url),JSON.stringify({source:'Bluetooth SIG Company Identifiers via NordicSemiconductor/bluetooth-numbers-database (BSD-3-Clause)',cols,rows:out}));
console.log(out.length+' company IDs');
